  "hypotheses": [
    {
      "text": "IBM's sic_code in edgar.company_profiles is NULL or empty, so the inner join to company_dns.sic_codes_table produces no matching rows.",
      "how_to_test": "SELECT sic_code FROM edgar.company_profiles WHERE cik = 51143;"
    },
    {
      "text": "IBM's sic_code contains leading zeros (e.g., '0371') while the reference sic_codes_table stores the same code without leading zeros (e.g., '371'), causing a mismatch on the text join.",
      "how_to_test": "SELECT cp.sic_code AS profile_sic, TRIM(LEADING '0' FROM cp.sic_code) AS stripped_sic, sic.sic_code AS ref_sic\nFROM edgar.company_profiles cp\nLEFT JOIN company_dns.sic_codes_table sic ON TRIM(LEADING '0' FROM cp.sic_code) = sic.sic_code\nWHERE cp.cik = 51143;"
    },
    {
      "text": "IBM's sic_code is a valid 4‑digit SIC that is simply absent from company_dns.sic_codes_table due to a coverage gap in the reference data (e.g., a newer or industry‑specific code not yet loaded).",
      "how_to_test": "SELECT cp.sic_code\nFROM edgar.company_profiles cp\nLEFT JOIN company_dns.sic_codes_table sic ON cp.sic_code = sic.sic_code\nWHERE cp.cik = 51143 AND sic.sic_code IS NULL;"
    },
    {
      "text": "IBM's sic_code reflects a historic or retired SIC that has been removed from the active company_dns reference list (real‑world change in classification), so no current reference row exists.",
      "how_to_test": "SELECT cp.sic_code\nFROM edgar.company_profiles cp\nWHERE cp.cik = 51143\n  AND NOT EXISTS (SELECT 1 FROM company_dns.sic_codes_table sic WHERE sic.sic_code = cp.sic_code);"
    }
  ]
}
